    'Em': ['E2','B2','E3','G3','B3','G3','E3','B2'],
}

# Lead melody: bar keyed by (chord, pattern_index)
lead_mel = {
    ('Am',0): [(0,'A4'),(2,'C5'),(4,'E5'),(6,'D5'),(8,'C5'),(10,'A4'),(12,'B4'),(14,'G4')],
